function get_site_content(): array
{
    $definitions = content_definitions();
    $values = array_map(
        static fn (array $definition): string => $definition['default'],
        $definitions
    );

    try {
        $rows = database()->query('SELECT content_key, content_value FROM page_content')->fetchAll();
    } catch (PDOException $exception) {
        if ($exception->getCode() !== '42S02' && $exception->getCode() !== '42P01') {
            throw $exception;
        }
        return $values;
    }

    foreach ($rows as $row) {
        $key = (string) $row['content_key'];
        if (array_key_exists($key, $definitions)) {
            $values[$key] = (string) $row['content_value'];
        }
    }

    return $values;
}
